using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.Serialization;

internal static class GearLinkLightingFamilyTests
{
    private static int count;
    private static void Check(bool condition,string name){if(!condition)throw new Exception("Lighting family check failed: "+name);count++;}
    private static void Reject(Action action,string name){bool rejected=false;try{action();}catch(ArgumentException){rejected=true;}catch(IOException){rejected=true;}Check(rejected,name);}
    private static Dictionary<string,object> Obj(params object[] v){return GearLinkWorker.Obj(v);}
    private static GearDescriptor Device(int pid,byte report=7){var f=GearLinkWorker.LightingFamilyFor(pid);return new GearDescriptor{Id="test-"+pid,Pid=(ushort)pid,Page=(ushort)(f.Kind=="mouse"?0xFF01:0xFF00),Usage=1,InputLength=65,OutputLength=65,InputReports=new[]{report},OutputReports=new[]{report}};}
    private static Dictionary<string,object> Snapshot(Dictionary<string,object> state){return (Dictionary<string,object>)state["snapshot"];}
    private sealed class Fake
    {
        internal GearDescriptor Descriptor;internal readonly Dictionary<int,byte[]> Recipes=new Dictionary<int,byte[]>();internal readonly List<byte[]> Queries=new List<byte[]>(),Writes=new List<byte[]>();
        internal int MissingArea=-2,RejectedArea=-2,UnconfirmedArea=-2,ThrowArea=-2;internal int Awake=1,Sw,Wdl,Profile=1,Count=6,CurrentMode=2,Connection=-1;internal bool MalformedSw,ChangeProfile,ChangeDirection,ChangeUnwritten,DisconnectAfterWrite,MutateRequest;internal object Request;
        internal Fake(int pid){Descriptor=Device(pid);var f=GearLinkWorker.LightingFamilyFor(pid);foreach(int area in f.Areas){var b=new byte[f.Kind=="mouse"?13:18];b[0]=(byte)(f.Kind=="mouse"?0x12:0x25);b[1]=(byte)(f.Kind=="mouse"?3:14);b[2]=(byte)area;if(f.Kind=="mouse"){b[4]=2;b[5]=60;b[6]=10;b[7]=20;b[8]=30;b[10]=(byte)(area%2);b[11]=1;b[12]=(byte)(20+area);}else{b[4]=30;b[5]=60;b[6]=17;b[7]=255;b[8]=255;b[9]=10;b[10]=20;b[11]=30;b[12]=40;b[15]=50;}Recipes[area]=b;}}
        internal byte[] Query(byte[] p){Queries.Add((byte[])p.Clone());var f=GearLinkWorker.LightingFamilyFor(Descriptor.Pid);if(!GearLinkWorker.IsLightingFamilyQuery(Descriptor.Pid,p))throw new Exception("Fake saw non-lighting query.");byte[] b;
            if(p[0]==0x12&&p[1]==0&&p[2]==0){b=new byte[f.Kind=="mouse"?19:15];b[8]=(byte)Count;b[9]=(byte)CurrentMode;b[10]=(byte)(f.Kind=="mouse"?Profile-1:Profile);b[4]=1;b[11]=1;return b;}
            if(f.Kind=="mouse"&&p[1]==3||f.Kind=="keyboard"&&p[0]==0x25){int area=f.Kind=="mouse"?p[2]:0;if(area==MissingArea)throw new IOException("Synthetic missing area.");return (byte[])Recipes[area].Clone();}
            b=new byte[5];if(f.Kind=="mouse"&&p[1]==0&&p[2]==2)b[4]=(byte)(DisconnectAfterWrite&&Writes.Count>0?0:Awake);
            else if(f.Kind=="keyboard"&&p[0]==0x12&&p[1]==3)b[4]=(byte)(DisconnectAfterWrite&&Writes.Count>0?255:Connection>=0?Connection:f.Transport=="usb"?0:1);
            else if(p[0]==0x27||f.Kind=="mouse"&&p[2]==12)b[4]=(byte)(MalformedSw?2:Sw);else b[4]=(byte)Wdl;return b;
        }
        internal Dictionary<string,object> Read(){return GearLinkWorker.ReadLightingFamilyScope(Descriptor,Query);}
        internal GearLinkWorker.SettingReceipt Write(byte[] p){Writes.Add((byte[])p.Clone());var f=GearLinkWorker.LightingFamilyFor(Descriptor.Pid);int area=p.Length==5?-1:p[2];if(area==ThrowArea)throw new IOException("Synthetic disconnect during output.");var receipt=new GearLinkWorker.SettingReceipt{OutputCompleted=true,Acknowledged=true,Rejected=area==RejectedArea};if(receipt.Rejected)return receipt;
            if(p.Length==5)Sw=p[4];else if(area!=UnconfirmedArea){var b=Recipes[area];if(f.Kind=="mouse"){b[4]=p[4];b[5]=p[5];Array.Copy(p,6,b,6,3);b[10]=p[9];b[11]=p[10];b[12]=p[11];if(ChangeDirection)b[10]=(byte)(1-b[10]);}
                else {Array.Copy(p,4,b,4,14);CurrentMode=0;}}
            if(ChangeProfile)Profile++;if(ChangeUnwritten&&Recipes.ContainsKey(2))Recipes[2][12]++;
            if(MutateRequest){var map=Request as Dictionary<string,object>;if(map!=null)map["brightness"]=0;}
            return receipt;
        }
    }
    private static Dictionary<string,object> Value(){return Obj("color",new[]{101,102,103},"brightness",80);}
    private static Dictionary<string,object> Apply(Fake f,string setting="staticLighting",object value=null,bool noOp=false){return GearLinkWorker.ApplyLightingFamily(f.Descriptor,setting,value??Value(),noOp,f.Read,f.Write);}
    private static void Main(){try{Run();Console.WriteLine(GearLinkWorker.Json.Serialize(Obj("ok",true,"suite","lighting_families","checks",count,"hardwareAccess",false)));}catch(Exception e){Console.Error.WriteLine(e);Environment.Exit(1);}}
    internal static void Run()
    {
        int[] mice={6802,6804,6934,6936,7011,7013,7015,7017,7180,7182,7273,7275},keyboards={6787,6789,6975,6978,7204,7205};
        Check(RogControl.GearLinkLightingModelFacts.All.Length==22,"one shared normal lighting registry");
        foreach(var shared in RogControl.GearLinkLightingModelFacts.All){Check(RogControl.GearLinkLightingModelFacts.Supports(shared.Pid)&&RogControl.GearLinkLightingModelFacts.KindForPid(shared.Pid)==shared.Kind,"shared exact identity");Check(RogControl.GearLinkLightingModelFacts.ModelForPid(shared.Pid)==shared.Model&&RogControl.GearLinkLightingModelFacts.TransportForPid(shared.Pid)==shared.Transport,"shared display metadata");Check(RogControl.GearLinkLightingModelFacts.AreasForPid(shared.Pid).SequenceEqual(shared.Areas)&&shared.PrimaryArea==shared.Areas[0],"shared areas contract");Check(RogControl.GearLinkLightingModelFacts.IsLightingOnly(shared.Pid)==GearLinkWorker.LightingOnlyFamily(shared.Pid),"shared minimal gate");}
        foreach(int pid in mice.Concat(keyboards)){
            var f=GearLinkWorker.LightingFamilyFor(pid);Check(GearLinkWorker.Kind(pid)==f.Kind,"kind "+pid);Check(GearLinkWorker.Transport(pid)==f.Transport,"transport "+pid);Check(GearLinkWorker.Model(pid)==f.Name,"name "+pid);Check(GearLinkWorker.LightingOnlyFamily(pid),"minimal gate "+pid);Check(!GearLinkWorker.LegacyKeyboard(pid),"no legacy expansion "+pid);
            var fake=new Fake(pid);var read=fake.Read();var s=Snapshot(read);Check((bool)read["online"]&&(bool)s["uniformStaticLightingProtocolAvailable"],"prepared read "+pid);Check(!(bool)s["lightingHardwareVerified"],"no fabricated validation "+pid);Check(((string[])read["setCapabilities"]).OrderBy(x=>x).SequenceEqual(new[]{"lightingSoftwareMode","staticLighting"}),"only minimal setters "+pid);
            Check(((Dictionary<string,object>[])s["lightingAreas"]).Select(a=>(int)a["area"]).SequenceEqual(f.Areas),"exact areas "+pid);Check((int)((Dictionary<string,object>)s["lighting"])["area"]==f.Areas[0],"primary area "+pid);
            Check(!s.ContainsKey("dpiStages")&&!s.ContainsKey("pollingRate")&&!s.ContainsKey("calibrationInfo"),"no sensor current guesses "+pid);
            var plan=GearLinkWorker.BuildLightingFamilyPlan(pid,"staticLighting",Value(),s);Check(plan.Length==f.Areas.Length,"whole plan "+pid);foreach(var step in plan){Check(GearLinkWorker.IsLightingFamilyWrite(pid,step.Packet),"golden allow "+pid);if(f.Kind=="mouse")Check(step.Packet.SequenceEqual(new byte[]{81,40,(byte)step.Area,0,0,80,101,102,103,(byte)(step.Area%2),0,(byte)(20+step.Area)}),"mouse bytes "+pid);else Check(step.Packet.SequenceEqual(new byte[]{81,44,0,0,30,80,0,255,255,101,102,103,0,0,0,0,0,0}),"keyboard bytes "+pid);}
            var copy=plan[0].Packet;copy[4]=255;Check(plan[0].Packet[4]!=255,"immutable packet "+pid);var areas=f.Areas;areas[0]=2;Check(f.Areas[0]!=2,"immutable registry "+pid);
            foreach(string op in new[]{"calibrationStart","calibrationRead","keys","pair","firmwareUpdate"})Reject(()=>GearLinkWorker.ValidateLightingFamilyRequest(op,""),"non-scope operation "+pid+op);
            foreach(string setting in new[]{"dpiStage","pollingRate","mouseLighting","calibrationInfo","oledMode","keyAssignment"})Reject(()=>GearLinkWorker.ValidateLightingFamilyRequest("set",setting),"non-scope setter "+pid+setting);
            foreach(byte[] bad in new[]{GearLinkWorker.Packet(0x12,4,0),GearLinkWorker.Packet(0x12,6,0),GearLinkWorker.Packet(0x12,20,1),GearLinkWorker.Packet(0x7D,32,1),GearLinkWorker.Packet(0xA0,0,0)})Check(!GearLinkWorker.IsLightingFamilyQuery(pid,bad),"reject unrelated query "+pid);
            foreach(byte[] bad in new[]{GearLinkWorker.Packet(0x51,49,4,3,0),GearLinkWorker.Packet(0x51,35,0,0,0,0,0,0),GearLinkWorker.Packet(0x51,66,0,0),GearLinkWorker.Packet(0x73,0,0,0)})Check(!GearLinkWorker.IsLightingFamilyWrite(pid,bad),"reject unrelated write "+pid);
            var query=f.Kind=="mouse"?GearLinkWorker.Packet(0x12,3,(ushort)f.Areas[0]):GearLinkWorker.Packet(0x25,14,0);var input=new byte[8];input[0]=7;Array.Copy(query,0,input,1,4);Check(GearLinkWorker.ResponseMatches(pid,7,query,input,input.Length),"strict matching "+pid);input[3]++;Check(!GearLinkWorker.ResponseMatches(pid,7,query,input,input.Length),"reject wrong area/index "+pid);input[3]--;input[0]=3;Check(!GearLinkWorker.ResponseMatches(pid,7,query,input,input.Length),"reject guessed report "+pid);
            var result=Apply(fake);Check((bool)result["writeConfirmed"]&&Text(result,"appliedState")=="confirmed","confirmed apply "+pid);Check(fake.Writes.Count==f.Areas.Length,"all area outputs "+pid);Check(GearLinkWorker.MatchesLightingFamilyAfter(pid,"staticLighting",Value(),s,Snapshot(result),f.Areas),"complete readback "+pid);
            var owned=new Fake(pid){Sw=1};var ownerRead=owned.Read();Check(!((string[])ownerRead["setCapabilities"]).Contains("staticLighting")&&((string[])ownerRead["setCapabilities"]).Contains("lightingSoftwareMode"),"software owner gate "+pid);var mode=Apply(owned,"lightingSoftwareMode",false);Check((bool)mode["writeConfirmed"]&&owned.Writes.Count==1&&owned.Writes[0].SequenceEqual(f.Kind=="mouse"?new byte[]{81,48,0,0,0}:new byte[]{116,0,0,0,0}),"explicit ownership output "+pid);
        }
        foreach(int pid in new[]{7547,7587,6976,7206,1,0,65535}){Check(GearLinkWorker.Kind(pid)=="unknown"&&!GearLinkWorker.LightingOnlyFamily(pid),"exclude catalog mode "+pid);Check(!GearLinkWorker.IsLightingFamilyWrite(pid,new byte[]{81,40,0,0,0,100,1,2,3,0,0,1}),"unknown writer "+pid);Check(!RogControl.GearLinkLightingModelFacts.Supports(pid)&&RogControl.GearLinkLightingModelFacts.Lookup(pid)==null&&RogControl.GearLinkLightingModelFacts.AreasForPid(pid).Length==0,"shared unknown cannot acquire scope");}
        Check(GearLinkWorker.LegacyKeyboard(7586)&&GearLinkWorker.LegacyKeyboard(7588)&&GearLinkWorker.ResponsePrefixLength(7586,new byte[]{0x25,14,0,0})==2,"existing keyboard compatibility");Check(!GearLinkWorker.LightingOnlyFamily(7546)&&!GearLinkWorker.LightingOnlyFamily(7588),"full current devices unchanged");
        foreach(object bad in new object[]{null,true,"80",80.0,80.5,-1,101,Int64.MaxValue}){var value=Value();value["brightness"]=bad;var f=new Fake(7180);Reject(()=>Apply(f,"staticLighting",value),"strict brightness");Check(f.Queries.Count==0&&f.Writes.Count==0,"invalid schema before native delegates");}
        foreach(object color in new object[]{null,"RGB",new[]{1,2},new[]{1,2,3,4},new object[]{1,true,3},new object[]{1,2.0,3},new[]{-1,2,3},new[]{1,256,3},Obj("r",1,"g",2,"b",3)}){var f=new Fake(7180);Reject(()=>Apply(f,"staticLighting",Obj("color",color,"brightness",80)),"strict RGB");Check(f.Queries.Count==0&&f.Writes.Count==0,"RGB schema early");}
        var extra=Value();extra["area"]=3;Reject(()=>Apply(new Fake(7180),"staticLighting",extra),"unknown fields");Reject(()=>Apply(new Fake(7180),"lightingSoftwareMode",1),"strict ownership type");
        foreach(int missing in new[]{0,1,2}){var f=new Fake(7180){MissingArea=missing};var s=Snapshot(f.Read());Check(!(bool)s["uniformStaticLightingProtocolAvailable"],"incomplete areas block uniform");Reject(()=>Apply(f),"missing area before first output");Check(f.Writes.Count==0,"missing no outputs");}
        foreach(var f in new[]{new Fake(7180){Sw=1},new Fake(7180){Wdl=1},new Fake(7180){MalformedSw=true},new Fake(7180){Awake=0},new Fake(7180){Awake=2},new Fake(7180){Count=0},new Fake(7180){Profile=7}}){Reject(()=>Apply(f),"owner/online/profile gate");Check(f.Writes.Count==0,"blocked no output");}
        foreach(int connection in new[]{2,3,255,1}){var f=new Fake(6787){Connection=connection};Check(!(bool)f.Read()["online"],"exact USB connection boundary");}
        var invalidDescriptor=Device(7180);invalidDescriptor.Page=0xFF00;Check(!GearLinkWorker.LightingFamilyCollection(invalidDescriptor),"wrong direct page");invalidDescriptor=Device(7180);invalidDescriptor.OutputReports=new byte[]{3,7};Check(!GearLinkWorker.LightingFamilyCollection(invalidDescriptor),"ambiguous actual report");invalidDescriptor=Device(7182);invalidDescriptor.Page=0xFF02;invalidDescriptor.ReceiverPid=7508;invalidDescriptor.ReceiverId="receiver";Check(GearLinkWorker.LightingFamilyCollection(invalidDescriptor)&&invalidDescriptor.SelectReport(null)==7,"real routed report");invalidDescriptor.Pid=7180;Check(!GearLinkWorker.LightingFamilyCollection(invalidDescriptor),"no unproven wired PID routed as RF");
        foreach(int pid in new[]{7180,6787}){var d=Device(pid);d.InputLength=18;Check(!GearLinkWorker.LightingFamilyCollection(d),"complete reply descriptor length");d=Device(pid);d.OutputLength=12;Check(!GearLinkWorker.LightingFamilyCollection(d),"complete setting descriptor length");}
        foreach(string failure in new[]{"rejected","unconfirmed","exception","profile","direction","unwritten","disconnect"}){var f=new Fake(7180);if(failure=="rejected")f.RejectedArea=1;if(failure=="unconfirmed")f.UnconfirmedArea=1;if(failure=="exception")f.ThrowArea=1;if(failure=="profile")f.ChangeProfile=true;if(failure=="direction")f.ChangeDirection=true;if(failure=="unwritten")f.ChangeUnwritten=true;if(failure=="disconnect")f.DisconnectAfterWrite=true;var r=Apply(f);Check(!(bool)r["writeConfirmed"],"unconfirmed "+failure);Check(f.Writes.Count<3,"stop subsequent area "+failure);Check(Text(r,"appliedState")==((failure=="rejected"||failure=="unconfirmed"||failure=="exception")?"partial":"unconfirmed"),"honest partial "+failure);Check(!f.Writes.Any(p=>p[2]==2),"no third output "+failure);}
        var noOpFake=new Fake(7180);Reject(()=>Apply(noOpFake,"staticLighting",Value(),true),"read-only changed rejection");Check(noOpFake.Writes.Count==0,"no-op guard no setting output");var already=new Fake(7180);Apply(already);already.Writes.Clear();var alreadyState=Apply(already);Check((bool)alreadyState["writeConfirmed"]&&!(bool)alreadyState["writeAttempted"]&&already.Writes.Count==0,"already set all areas");
        var mutated=new Fake(7180){MutateRequest=true};var submitted=Value();mutated.Request=submitted;var frozen=Apply(mutated,"staticLighting",submitted);Check((bool)frozen["writeConfirmed"]&&mutated.Writes.All(p=>p[5]==80),"immutable submitted request and plan");
        var deadline=new Fake(7180);int deadlineChecks=0;var bounded=GearLinkWorker.ApplyLightingFamily(deadline.Descriptor,"staticLighting",Value(),false,deadline.Read,deadline.Write,()=>deadlineChecks++==0?0:16000);Check(Text(bounded,"appliedState")=="partial"&&deadline.Writes.Count==1,"budget stops subsequent area before output");
        deadline=new Fake(7180);bounded=GearLinkWorker.ApplyLightingFamily(deadline.Descriptor,"staticLighting",Value(),false,deadline.Read,deadline.Write,()=>16000);Check(Text(bounded,"appliedState")=="unconfirmed"&&!(bool)bounded["writeAttempted"]&&deadline.Writes.Count==0,"no incomplete transaction at deadline");
        var failureState=GearLinkWorker.FailedLightingFamilyScope(Device(7180),new IOException("Synthetic read failure"));Check(!(bool)failureState["online"]&&!Snapshot(failureState).ContainsKey("lighting")&&((string[])failureState["setCapabilities"]).Length==0,"failed scan does not invent state");
        // Exercise the actual final transport entry without constructing/opening a native handle.
        foreach(int pid in mice.Concat(keyboards)){var d=Device(pid);var h=(GearHid)FormatterServices.GetUninitializedObject(typeof(GearHid));typeof(GearHid).GetField("descriptor",BindingFlags.Instance|BindingFlags.NonPublic).SetValue(h,d);Reject(()=>h.WriteSetting(7,new byte[]{81,49,4,0,3,0}),"final transport rejects unrelated setter");Reject(()=>h.Query(7,new byte[]{18,6,0,0}),"final transport rejects calibration getter");Reject(()=>h.Query(3,new byte[]{18,0,0,0}),"final transport rejects wrong report");}
    }
    private static string Text(Dictionary<string,object> o,string key){return GearLinkWorker.Text(o,key);}
}
